        internal static bool IsRussian(string locale) => locale != null && locale.StartsWith("ru", StringComparison.OrdinalIgnoreCase);
        internal static string Get(string key, string locale) => Entries.TryGetValue(key, out var pair) ? pair[IsRussian(locale) ? 1 : 0] : key;
        internal static string Literal(string text, string locale)
        {
            foreach (var entry in Entries.Values)
                if (string.Equals(entry[0], text, StringComparison.OrdinalIgnoreCase)) return entry[IsRussian(locale) ? 1 : 0];
            return text;
        }
    }
